<?php

declare(strict_types=1);

namespace App\Data;

/** Authored, progressively more specific clues; titles and aliases are server-side answers. */
final class AnimeCluesPartOne
{
    public static function all(): array
    {
        $third = [
            'pl' => 'W tej historii ważną postacią jest {character}.',
            'en' => 'An important character in this story is {character}.',
            'de' => 'Eine wichtige Figur in dieser Geschichte ist {character}.',
            'fr' => 'Un personnage important de cette histoire est {character}.',
            'es' => 'Un personaje importante de esta historia es {character}.',
            'ru' => 'Важный персонаж этой истории — {character}.',
        ];
        $result = [];
        foreach ([...self::first(), ...self::second(), ...self::third(), ...self::fourth(), ...self::fifth()] as $row) {
            [$id, $franchise, $title, $aliases, $character, $source, $pairs] = $row;
            $clues = [];
            foreach (array_keys($third) as $index => $locale) {
                $clues[$locale] = [...$pairs[$index], strtr($third[$locale], ['{character}' => $character])];
            }
            $result[] = [
                'id' => $id, 'title' => $title, 'aliases' => array_values(array_unique([$title, ...$aliases])),
                'franchise' => $franchise, 'clues' => $clues, 'sourceUrl' => $source,
            ];
        }

        return $result;
    }

